-- Restore Receivables, Payables, and Order History
BEGIN;
CREATE TEMP TABLE staging_products (LIKE products INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE staging_product_variants (LIKE product_variants INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE staging_product_supplier_links (LIKE product_supplier_links INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE staging_sales_orders (LIKE sales_orders INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE staging_sales_order_items (LIKE sales_order_items INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE staging_purchase_orders (LIKE purchase_orders INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE staging_purchase_order_items (LIKE purchase_order_items INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE staging_returns (LIKE returns INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE staging_return_items (LIKE return_items INCLUDING DEFAULTS) ON COMMIT DROP;
CREATE TEMP TABLE staging_document_history (LIKE document_history INCLUDING DEFAULTS) ON COMMIT DROP;

UPDATE payments p
SET sales_order_id = s.id
FROM sales_orders s
WHERE p.reference = s.order_number AND p.direction = 'IN' AND p.sales_order_id IS NULL;

UPDATE payments p
SET purchase_order_id = po.id
FROM purchase_orders po
WHERE p.reference = po.order_number AND p.direction = 'OUT' AND p.purchase_order_id IS NULL;

COMMIT;